macro_rules! deps {
    () => {
        LifetimeSource!();
        LifetimeKind!();
        LifetimeSyntax!();
    };
}

macro_rules! Lifetime {
    () => {
        deps!();
        # [doc = " A lifetime. The valid field combinations are non-obvious and not all"] # [doc = " combinations are possible. The following example shows some of"] # [doc = " them. See also the comments on `LifetimeKind` and `LifetimeSource`."] # [doc = ""] # [doc = " ```"] # [doc = " #[repr(C)]"] # [doc = " struct S<'a>(&'a u32);       // res=Param, name='a, source=Reference, syntax=ExplicitBound"] # [doc = " unsafe extern \"C\" {"] # [doc = "     fn f1(s: S);             // res=Param, name='_, source=Path, syntax=Implicit"] # [doc = "     fn f2(s: S<'_>);         // res=Param, name='_, source=Path, syntax=ExplicitAnonymous"] # [doc = "     fn f3<'a>(s: S<'a>);     // res=Param, name='a, source=Path, syntax=ExplicitBound"] # [doc = " }"] # [doc = ""] # [doc = " struct St<'a> { x: &'a u32 } // res=Param, name='a, source=Reference, syntax=ExplicitBound"] # [doc = " fn f() {"] # [doc = "     _ = St { x: &0 };        // res=Infer, name='_, source=Path, syntax=Implicit"] # [doc = "     _ = St::<'_> { x: &0 };  // res=Infer, name='_, source=Path, syntax=ExplicitAnonymous"] # [doc = " }"] # [doc = ""] # [doc = " struct Name<'a>(&'a str);    // res=Param,  name='a, source=Reference, syntax=ExplicitBound"] # [doc = " const A: Name = Name(\"a\");   // res=Static, name='_, source=Path, syntax=Implicit"] # [doc = " const B: &str = \"\";          // res=Static, name='_, source=Reference, syntax=Implicit"] # [doc = " static C: &'_ str = \"\";      // res=Static, name='_, source=Reference, syntax=ExplicitAnonymous"] # [doc = " static D: &'static str = \"\"; // res=Static, name='static, source=Reference, syntax=ExplicitBound"] # [doc = ""] # [doc = " trait Tr {}"] # [doc = " fn tr(_: Box<dyn Tr>) {}     // res=ImplicitObjectLifetimeDefault, name='_, source=Other, syntax=Implicit"] # [doc = ""] # [doc = " fn capture_outlives<'a>() ->"] # [doc = "     impl FnOnce() + 'a       // res=Param, ident='a, source=OutlivesBound, syntax=ExplicitBound"] # [doc = " {"] # [doc = "     || {}"] # [doc = " }"] # [doc = ""] # [doc = " fn capture_precise<'a>() ->"] # [doc = "     impl FnOnce() + use<'a>  // res=Param, ident='a, source=PreciseCapturing, syntax=ExplicitBound"] # [doc = " {"] # [doc = "     || {}"] # [doc = " }"] # [doc = ""] # [doc = " // (commented out because these cases trigger errors)"] # [doc = " // struct S1<'a>(&'a str);   // res=Param, name='a, source=Reference, syntax=ExplicitBound"] # [doc = " // struct S2(S1);            // res=Error, name='_, source=Path, syntax=Implicit"] # [doc = " // struct S3(S1<'_>);        // res=Error, name='_, source=Path, syntax=ExplicitAnonymous"] # [doc = " // struct S4(S1<'a>);        // res=Error, name='a, source=Path, syntax=ExplicitBound"] # [doc = " ```"] # [doc = ""] # [doc = " Some combinations that cannot occur are `LifetimeSyntax::Implicit` with"] # [doc = " `LifetimeSource::OutlivesBound` or `LifetimeSource::PreciseCapturing`"] # [doc = " — there's no way to \"elide\" these lifetimes."] # [derive (Debug , Copy , Clone , HashStable_Generic)] # [repr (align (4))] pub struct Lifetime { # [stable_hasher (ignore)] pub hir_id : HirId , # [doc = " Either a named lifetime definition (e.g. `'a`, `'static`) or an"] # [doc = " anonymous lifetime (`'_`, either explicitly written, or inserted for"] # [doc = " things like `&type`)."] pub ident : Ident , # [doc = " Semantics of this lifetime."] pub kind : LifetimeKind , # [doc = " The context in which the lifetime occurred. See `Lifetime::suggestion`"] # [doc = " for example use."] pub source : LifetimeSource , # [doc = " The syntax that the user used to declare this lifetime. See"] # [doc = " `Lifetime::suggestion` for example use."] pub syntax : LifetimeSyntax , }
    };
}

Lifetime!()